test('paginate: exact fit (20 items, pageSize 20) -> one full page, no trailing empty', () => {
  const items = Array.from({ length: 20 }, (_, i) => i + 1);
  assert.deepEqual(paginate(items, 20), [items]);
});
test('paginate: multiple of pageSize (40 items, pageSize 20) -> two full pages', () => {
  const items = Array.from({ length: 40 }, (_, i) => i + 1);
  assert.deepEqual(paginate(items, 20), [items.slice(0, 20), items.slice(20)]);
});
test('paginate: non-multiple (21 items, pageSize 20) -> full page + remainder, no trailing empty', () => {
  const items = Array.from({ length: 21 }, (_, i) => i + 1);
  assert.deepEqual(paginate(items, 20), [items.slice(0, 20), [21]]);
});
